// Package genquestions parses helm files and generates the questions files based on it
package genquestions

import (
	"bytes"
	"cmp"
	"fmt"
	"os"
	"slices"
	"strconv"
	"strings"

	"github.com/tidwall/gjson"
	"go.yaml.in/yaml/v4"
)

const annotationKey = "x-rancher-question"

// DefaultHeader is written at the top of the questions file unless overridden.
const DefaultHeader = "Generated by helm questions from the x-rancher-question annotations in the values schema.\n" +
	"Do not edit, update the annotations and run helm questions again."

// Options are the inputs and outputs of Generate.
type Options struct {
	// ValuesFilename is the helm chart values file, used for defaults and types.
	ValuesFilename string
	// SchemaFilename is the values JSON schema annotated with x-rancher-question.
	SchemaFilename string
	// QuestionsFilename is the file to write, "-" writes to stdout.
	QuestionsFilename string
	// Header is written as a comment at the top of the questions file, empty for none.
	Header string
}

// question is a question being built. Fields are ordered as they are written.
type question struct {
	fields        *yaml.Node // mapping node
	variable      string
	order         float64
	subquestionOf string
}

// Generate reads the schema and values files and writes the questions file.
func Generate(opts Options) error {
	schema, err := os.ReadFile(opts.SchemaFilename)
	if err != nil {
		return err
	}
	if !gjson.ValidBytes(schema) {
		return fmt.Errorf("%s: invalid JSON", opts.SchemaFilename)
	}
	values, err := readValues(opts.ValuesFilename)
	if err != nil {
		return err
	}
	out, err := build(schema, values, opts.Header)
	if err != nil {
		return err
	}
	if opts.QuestionsFilename == "-" {
		_, err = os.Stdout.Write(out)
		return err
	}
	return os.WriteFile(opts.QuestionsFilename, out, 0o644)
}

func readValues(filename string) (*yaml.Node, error) {
	data, err := os.ReadFile(filename)
	if err != nil {
		return nil, err
	}
	var doc yaml.Node
	if err := yaml.Unmarshal(data, &doc); err != nil {
		return nil, fmt.Errorf("%s: %w", filename, err)
	}
	if doc.Kind == yaml.DocumentNode && len(doc.Content) > 0 {
		return resolve(doc.Content[0]), nil
	}
	return nil, nil
}

// build generates the questions file content from the JSON schema and the parsed values.
func build(schema []byte, values *yaml.Node, header string) ([]byte, error) {
	var questions []*question
	for _, key := range annotatedKeys(gjson.ParseBytes(schema), nil, nil) {
		qs, err := toQuestions(key, values)
		if err != nil {
			return nil, err
		}
		questions = append(questions, qs...)
	}
	if err := validateSubquestions(questions); err != nil {
		return nil, err
	}

	file := questionsFile(questions)
	var buf bytes.Buffer
	if header != "" {
		for line := range strings.SplitSeq(strings.TrimRight(header, "\n"), "\n") {
			buf.WriteString(strings.TrimRight("# "+line, " "))
			buf.WriteByte('\n')
		}
	}
	body, err := yaml.Dump(file, yaml.WithV3Defaults(), yaml.WithIndent(2), yaml.WithLineWidth(-1))
	if err != nil {
		return nil, err
	}
	buf.Write(body)
	return buf.Bytes(), nil
}

// annotatedKey is a schema object with an x-rancher-question annotation.
type annotatedKey struct {
	// path is the key path in values.yaml, the schema "properties" keywords removed.
	path   []string
	schema gjson.Result
}

// annotatedKeys finds the annotated schema objects, parents before children.
func annotatedKeys(node gjson.Result, path []string, found []annotatedKey) []annotatedKey {
	if node.IsObject() && node.Get(annotationKey).Exists() {
		found = append(found, annotatedKey{path: slices.Clone(path), schema: node})
	}
	if !node.IsObject() && !node.IsArray() {
		return found
	}
	i := 0
	node.ForEach(func(key, value gjson.Result) bool {
		segment := key.String()
		if node.IsArray() {
			segment = strconv.Itoa(i)
			i++
		}
		next := path
		if segment != "properties" {
			next = append(slices.Clone(path), segment)
		}
		found = annotatedKeys(value, next, found)
		return true
	})
	return found
}

func toQuestions(key annotatedKey, values *yaml.Node) ([]*question, error) {
	annotation := key.schema.Get(annotationKey)
	var annotations []gjson.Result
	if annotation.IsArray() {
		annotations = annotation.Array()
	} else {
		annotations = []gjson.Result{annotation}
	}

	var questions []*question
	for _, a := range annotations {
		q, err := toQuestion(key, a, values)
		if err != nil {
			return nil, err
		}
		questions = append(questions, q)
	}
	return questions, nil
}

func toQuestion(key annotatedKey, annotation gjson.Result, values *yaml.Node) (*question, error) {
	relative := annotation.Get("variable")
	valuePath := slices.Clone(key.path)
	if s := relative.String(); relative.Exists() && s != "" {
		valuePath = append(valuePath, strings.Split(s, ".")...)
	}
	variable := strings.Join(valuePath, ".")
	value := lookup(values, valuePath)

	// A relative variable points inside the annotated key: its schema does not describe the value.
	valueSchema := key.schema
	if relative.Exists() && relative.Type != gjson.Null {
		valueSchema = gjson.Result{}
	}

	label, order := annotation.Get("label"), annotation.Get("order")
	subquestionOf := annotation.Get("subquestion_of")
	switch {
	case isNull(label):
		return nil, fmt.Errorf("%s: missing label", variable)
	case isNull(order):
		return nil, fmt.Errorf("%s: missing order", variable)
	case isNull(annotation.Get("group")) && isNull(subquestionOf):
		return nil, fmt.Errorf("%s: missing group", variable)
	case order.Type != gjson.Number:
		return nil, fmt.Errorf("%s: order must be a number", variable)
	}

	q := &question{
		fields:        &yaml.Node{Kind: yaml.MappingNode, Tag: "!!map"},
		variable:      variable,
		order:         order.Float(),
		subquestionOf: subquestionOf.String(),
	}
	set := func(k string, v *yaml.Node) {
		if v != nil && (v.Kind != yaml.ScalarNode || v.Tag != "!!null") {
			q.fields.Content = append(q.fields.Content, scalar(k), v)
		}
	}

	typ := annotation.Get("type")
	set("variable", scalar(variable))
	set("label", jsonNode(label))
	set("description", jsonNode(firstSet(annotation.Get("description"), valueSchema.Get("description"))))
	if isNull(typ) {
		set("type", scalar(inferType(valueSchema, value)))
	} else {
		set("type", jsonNode(typ))
	}
	if annotation.Get("default").Exists() {
		set("default", jsonNode(annotation.Get("default")))
	} else {
		set("default", copyNode(value))
	}
	if isNull(typ) || typ.String() == "enum" {
		options := firstSet(annotation.Get("options"), valueSchema.Get("enum"))
		emptyLabel := firstSet(annotation.Get("empty_option_label")).String()
		if emptyLabel == "" {
			emptyLabel = "None"
		}
		set("options", labelEmptyOption(jsonNode(options), emptyLabel))
	}

	annotation.ForEach(func(k, v gjson.Result) bool {
		switch k.String() {
		case "variable", "label", "description", "type", "default", "options", "empty_option_label":
		default:
			set(k.String(), jsonNode(v))
		}
		return true
	})
	return q, nil
}

func inferType(schema gjson.Result, value *yaml.Node) string {
	valueTag := ""
	if value != nil && value.Kind == yaml.ScalarNode {
		valueTag = value.Tag
	}
	switch {
	case schema.Get("enum").Exists() && schema.Get("enum").Type != gjson.Null:
		return "enum"
	case schema.Get("type").String() == "boolean" || valueTag == "!!bool":
		return "boolean"
	case schema.Get("type").String() == "integer" || valueTag == "!!int" || valueTag == "!!float":
		return "int"
	}
	return "string"
}

// labelEmptyOption turns an options list with a "" option into a value: label map,
// as the Rancher dashboard shows a "" option as an empty label.
func labelEmptyOption(options *yaml.Node, emptyLabel string) *yaml.Node {
	if options == nil || options.Kind != yaml.SequenceNode {
		return options
	}
	hasEmpty := slices.ContainsFunc(options.Content, func(n *yaml.Node) bool {
		return n.Kind == yaml.ScalarNode && n.Tag == "!!str" && n.Value == ""
	})
	if !hasEmpty {
		return options
	}
	m := &yaml.Node{Kind: yaml.MappingNode, Tag: "!!map"}
	for _, option := range options.Content {
		label := option
		if option.Kind == yaml.ScalarNode && option.Value == "" {
			label = scalar(emptyLabel)
		}
		m.Content = append(m.Content, scalar(option.Value), label)
	}
	return m
}

// validateSubquestions checks the subquestions point to a question, Rancher only supports one level.
func validateSubquestions(questions []*question) error {
	variables := map[string]bool{}
	parents := map[string]bool{}
	for _, q := range questions {
		variables[q.variable] = true
		if q.subquestionOf != "" {
			parents[q.subquestionOf] = true
		}
	}
	for _, q := range questions {
		if q.subquestionOf == "" {
			continue
		}
		if !variables[q.subquestionOf] {
			return fmt.Errorf("%s: unknown subquestion_of %s", q.variable, q.subquestionOf)
		}
		if parents[q.variable] {
			return fmt.Errorf("%s: subquestions cannot have subquestions", q.variable)
		}
	}
	return nil
}

// questionsFile sorts the questions and nests the subquestions under their parent.
func questionsFile(questions []*question) *yaml.Node {
	var parents, subquestions []*question
	for _, q := range questions {
		if q.subquestionOf == "" {
			parents = append(parents, q)
		} else {
			subquestions = append(subquestions, q)
		}
	}
	byOrder := func(a, b *question) int { return cmp.Compare(a.order, b.order) }
	slices.SortStableFunc(parents, byOrder)
	slices.SortStableFunc(subquestions, byOrder)

	list := &yaml.Node{Kind: yaml.SequenceNode, Tag: "!!seq"}
	for _, parent := range parents {
		fields := without(parent.fields, "order")
		var children []*yaml.Node
		for _, sub := range subquestions {
			if sub.subquestionOf == parent.variable {
				children = append(children, without(sub.fields, "order", "subquestion_of", "group"))
			}
		}
		if len(children) > 0 {
			fields.Content = append(fields.Content, scalar("subquestions"),
				&yaml.Node{Kind: yaml.SequenceNode, Tag: "!!seq", Content: children})
		}
		list.Content = append(list.Content, fields)
	}
	return &yaml.Node{Kind: yaml.MappingNode, Tag: "!!map", Content: []*yaml.Node{scalar("questions"), list}}
}
